import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def get_pkgs(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            for pkg in fw['topLevelPackages']:
                key = (name, fw['framework'], pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = get_pkgs(baseline)
a = get_pkgs(after)

changes = []
unchanged = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    proj, fw, pkg = key
    bv = b.get(key, 'N/A')
    av = a.get(key, 'N/A')
    if bv != av:
        changes.append((proj, fw, pkg, bv, av))
    else:
        unchanged.append((proj, fw, pkg, bv))

print('=== CHANGES ===')
if changes:
    for c in changes: print(f'{c[0]} ({c[1]}) | {c[2]} | {c[3]} -> {c[4]}')
else:
    print('None')
print()
print(f'=== UNCHANGED ({len(unchanged)} packages) ===')
for u in unchanged[:5]: print(f'{u[0]} ({u[1]}) | {u[2]} | {u[3]}')
if len(unchanged) > 5: print(f'... and {len(unchanged)-5} more')
"

